import{_ as r,c as t,o as a,a3 as n}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Foreign currencies","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/get-started/multi-currency.md","filePath":"master/finance/get-started/multi-currency.md","lastUpdated":1792041590000}'),o={name:"master/finance/get-started/multi-currency.md"};function c(s,e,i,u,h,l){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="foreign-currencies" tabindex="-1">Foreign currencies <a class="header-anchor" href="#foreign-currencies" aria-label="Permalink to &quot;Foreign currencies&quot;">​</a></h1><p>You may sell to a customer in euros while your books are in US dollars. Aureus lets you choose a currency on every invoice, bill and payment. It converts the amounts with your exchange rates and keeps your books in the company currency.</p><blockquote><p><strong>In simple words:</strong> Pick the currency on the document. Keep the exchange rate up to date. Aureus does the converting.</p></blockquote><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ol><li>The currency is <strong>active</strong>.</li><li>The currency has an <strong>exchange rate</strong> with a date on or before the document date.</li><li>The <strong>Exchange Difference</strong> journal and the gain and loss accounts are set in <a href="./default-accounts.html">Default accounts</a>.</li></ol><p>Activate currencies and add rates under <code>Invoices → Configurations → Currencies</code> or <code>Accounting → Configurations → Accounting → Currencies</code>. The steps are the same as in <a href="./../../sales/sales/products-prices/sell-in-other-currencies.html">Sell in other currencies</a>. The base currency and the other currency fields are in <a href="./../../general-settings/companies/currency.html">Currency</a>.</p><h2 id="currency-on-an-invoice-or-a-bill" tabindex="-1">Currency on an invoice or a bill <a class="header-anchor" href="#currency-on-an-invoice-or-a-bill" aria-label="Permalink to &quot;Currency on an invoice or a bill&quot;">​</a></h2><p>The <strong>Currency</strong> field is in the <strong>General</strong> section of an invoice or bill. It is required. It starts as your company currency, and only active currencies are offered.</p><ol><li>Create the invoice. See <a href="./../customer-invoices/create-invoice.html">Create an invoice</a>.</li><li>Choose the customer.</li><li>Choose the <strong>Currency</strong>, for example <code>INR</code>, before you add products.</li><li>Add the products.</li></ol><p>When you add a product to a line, Aureus converts the product&#39;s price from the company currency into the invoice currency. The conversion uses the rate valid on the <strong>Invoice Date</strong>. If you leave the date empty, it uses today.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Choose the currency first. A line takes its price when you pick the product, so choose the currency before you add products.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>After an invoice is posted, the currency can no longer be changed. Fix mistakes while the document is in <strong>Draft</strong>.</p></div><p>The company currency amount is kept on the invoice together with the rate used, and your reports show the company currency.</p><h2 id="how-a-rate-is-picked" tabindex="-1">How a rate is picked <a class="header-anchor" href="#how-a-rate-is-picked" aria-label="Permalink to &quot;How a rate is picked&quot;">​</a></h2><p>Aureus takes the latest rate that is dated on or before the document date. If a currency has no rate, Aureus treats the rate as 1, so nothing is converted. Add a rate before you create documents.</p><h2 id="currency-on-a-payment" tabindex="-1">Currency on a payment <a class="header-anchor" href="#currency-on-a-payment" aria-label="Permalink to &quot;Currency on a payment&quot;">​</a></h2><p>The payment form has a <strong>Currency</strong> field. It starts as the company currency. Use it when the customer pays in a different currency from the invoice. See <a href="./../payments/register-payment.html">Register a payment</a>.</p><h2 id="exchange-differences" tabindex="-1">Exchange differences <a class="header-anchor" href="#exchange-differences" aria-label="Permalink to &quot;Exchange differences&quot;">​</a></h2><p>Rates move between the day you invoice and the day you are paid. Suppose you invoiced 8,300 INR when 1 USD was 83 INR, which is 100 USD. The customer pays when 1 USD is 80 INR, which is 103.75 USD. The 3.75 USD difference is a <strong>gain</strong>.</p><p>When the payment is matched to the invoice and a difference remains, Aureus posts an entry in the <strong>Journal</strong> from <strong>Exchange Difference Entries</strong>. A gain goes to the <strong>Gain</strong> account and a loss to the <strong>Loss</strong> account. The entry is posted and matched on its own.</p><h2 id="check-your-set-up" tabindex="-1">Check your set-up <a class="header-anchor" href="#check-your-set-up" aria-label="Permalink to &quot;Check your set-up&quot;">​</a></h2><ul><li>Prices do not change: the currency has no rate, or the rate is dated in the future.</li><li>Error about the exchange difference journal: fill in <strong>Exchange Difference Entries</strong> in <a href="./default-accounts.html">Default accounts</a>.</li><li>The currency is missing in the picker: turn on its <strong>Status</strong>.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../sales/sales/products-prices/sell-in-other-currencies.html">Sell in other currencies</a></li><li><a href="./../../general-settings/companies/currency.html">Currency</a></li><li><a href="./default-accounts.html">Default accounts</a></li><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li></ul>',24)]))}const y=r(o,[["render",c]]);export{p as __pageData,y as default};
